import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"Problems Ershu can solve","description":"Decide whether Ershu fits your work across AI coding, internal documentation, cross-repository changes, and team handoffs.","frontmatter":{"page_id":"overview-use-cases","title":"Problems Ershu can solve","description":"Decide whether Ershu fits your work across AI coding, internal documentation, cross-repository changes, and team handoffs."},"headers":[],"relativePath":"en/overview/use-cases.md","filePath":"en/overview/use-cases.md","lastUpdated":1786627803000}'),n={name:"en/overview/use-cases.md"};function o(i,e,c,l,d,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="problems-ershu-can-solve" tabindex="-1">Problems Ershu can solve <a class="header-anchor" href="#problems-ershu-can-solve" aria-label="Permalink to &quot;Problems Ershu can solve&quot;">​</a></h1><p>Ershu organizes project context before people or AI ask a question. Each use case below maps to a feature you can test in your own project.</p><h2 id="ai-coding-spend-less-time-rebuilding-context" tabindex="-1">AI coding: spend less time rebuilding context <a class="header-anchor" href="#ai-coding-spend-less-time-rebuilding-context" aria-label="Permalink to &quot;AI coding: spend less time rebuilding context&quot;">​</a></h2><p>Coding agents often struggle with project conventions rather than syntax. An agent may see the current repository but miss an interface defined by another service. It may read an old document without knowing which commit that document describes.</p><p>Ershu exposes project-scoped, read-only MCP tools. A client can discover a project and then retrieve:</p><ul><li>project overviews and wiki sections;</li><li>repository trees, code indexes, and bounded sections of source;</li><li>project search, relationships, candidate change surfaces, and static runtime paths;</li><li>public interfaces, consumer contracts, and schemas;</li><li>commit, freshness, coverage, fallback, and truncation signals.</li></ul><p>This does not guarantee correct code. It helps an agent see project boundaries sooner and gives reviewers a better answer to the question, &quot;Where did that conclusion come from?&quot;</p><h3 id="a-safer-reading-order" tabindex="-1">A safer reading order <a class="header-anchor" href="#a-safer-reading-order" aria-label="Permalink to &quot;A safer reading order&quot;">​</a></h3><ol><li>Use MCP to identify the project, repositories, and current commits.</li><li>Read the project overview and relevant wiki sections for direction.</li><li>Narrow the area with search, relationships, or interface contracts.</li><li>Read the critical source last, then run the real tests locally.</li></ol><p>This sequence is easier to control than placing a large set of files into the prompt at once, and it avoids much of the code that has nothing to do with the task.</p><h2 id="internal-wiki-make-code-knowledge-useful-to-the-whole-team" tabindex="-1">Internal wiki: make code knowledge useful to the whole team <a class="header-anchor" href="#internal-wiki-make-code-knowledge-useful-to-the-whole-team" aria-label="Permalink to &quot;Internal wiki: make code knowledge useful to the whole team&quot;">​</a></h2><p>Repository knowledge affects more than the people writing code. Why a feature fails, where a field comes from, and who consumes an interface also matter to QA, product, support, delivery, and architecture work.</p><table tabindex="0"><thead><tr><th>Role</th><th>What the wiki can provide first</th><th>What still needs verification</th></tr></thead><tbody><tr><td>New developer</td><td>Project shape, repository responsibilities, entry points, and main workflows</td><td>Current source, tests, and historical context from maintainers</td></tr><tr><td>Maintainer</td><td>Configuration, module relationships, interfaces, and source citations</td><td>The actual branch, commit, and change under review</td></tr><tr><td>QA engineer</td><td>Interfaces, schemas, message channels, and failure paths</td><td>A running environment, test data, and acceptance rules</td></tr><tr><td>Product and support</td><td>Which modules deliver a feature, related documents, and searchable terms</td><td>Business rules, customer agreements, and release notes</td></tr><tr><td>Architecture and security</td><td>Repository relationships, public entry points, candidate dependencies, and access boundaries</td><td>Runtime evidence, security tests, and deployment configuration</td></tr></tbody></table><p>Wiki pages support Markdown, Mermaid diagrams, table-of-contents navigation, and source previews. Documents are grouped by repository and category, while one Ershu project can contain several repositories. The wiki is a shared starting point, not a replacement for source.</p><h2 id="cross-repository-changes-find-the-likely-impact-before-editing" tabindex="-1">Cross-repository changes: find the likely impact before editing <a class="header-anchor" href="#cross-repository-changes-find-the-likely-impact-before-editing" aria-label="Permalink to &quot;Cross-repository changes: find the likely impact before editing&quot;">​</a></h2><p>Many enterprise systems are divided by repository but shipped as one product. A change can start in the frontend, cross an API or message, pass through a service and schema, then affect a consumer owned by another team.</p><p>Ershu brings those clues into one project:</p><ul><li>the knowledge graph displays repository, directory, symbol, and dependency relationships;</li><li>change-surface queries find direct and related candidates around a path or symbol;</li><li>static runtime paths organize possible steps through calls and stored relationships;</li><li>interface contracts separate providers, consumers, public interfaces, and schemas;</li><li>cross-repository search can cover the whole project or one selected repository.</li></ul><p>Use these results to narrow the review area. Dynamic calls, reflection, runtime configuration, and external systems may not appear in static data, so releases still need tests and human review.</p><h2 id="handoffs-and-legacy-systems-search-the-project-before-asking-one-person" tabindex="-1">Handoffs and legacy systems: search the project before asking one person <a class="header-anchor" href="#handoffs-and-legacy-systems-search-the-project-before-asking-one-person" aria-label="Permalink to &quot;Handoffs and legacy systems: search the project before asking one person&quot;">​</a></h2><p>When a key maintainer leaves or a team inherits a poorly documented system, writing a new wiki by hand begins with a long source investigation. Ershu can build an initial view from current repositories, giving later interviews and manual notes a shared structure.</p><p>A practical workflow looks like this:</p><ol><li>Put the repositories that ship together into one project.</li><li>Complete the first full-project analysis.</li><li>Ask current maintainers to review the important documents and relationships, then add reasons and constraints that code cannot express.</li><li>Turn recurring questions into wiki reading paths or MCP guidance.</li><li>Use later runs and repository triggers to keep the factual layers current.</li></ol><p>Ershu can reconstruct what the code says now. It cannot recover business history that was never recorded in code, commits, or documents.</p><h2 id="useful-features-that-are-easy-to-miss" tabindex="-1">Useful features that are easy to miss <a class="header-anchor" href="#useful-features-that-are-easy-to-miss" aria-label="Permalink to &quot;Useful features that are easy to miss&quot;">​</a></h2><h3 id="_1-interface-contracts-are-queryable-on-their-own" tabindex="-1">1. Interface contracts are queryable on their own <a class="header-anchor" href="#_1-interface-contracts-are-queryable-on-their-own" aria-label="Permalink to &quot;1. Interface contracts are queryable on their own&quot;">​</a></h3><p>Ershu organizes facts from OpenAPI, GraphQL, Protobuf, Thrift, AsyncAPI, message channels, database schemas, generated clients, and selected framework routes. MCP clients can query consumer contracts, public interfaces, schemas, and recorded contract differences.</p><h3 id="_2-results-report-their-own-limits" tabindex="-1">2. Results report their own limits <a class="header-anchor" href="#_2-results-report-their-own-limits" aria-label="Permalink to &quot;2. Results report their own limits&quot;">​</a></h3><p>Search and relationship queries return the actual mode, fallback reason, coverage, status, and truncation signals. Documents and repository facts carry commit and freshness data. An empty result no longer has to mean &quot;nothing exists&quot;; the data may be missing, stale, or outside the current query boundary.</p><h3 id="_3-the-analysis-itself-is-inspectable" tabindex="-1">3. The analysis itself is inspectable <a class="header-anchor" href="#_3-the-analysis-itself-is-inspectable" aria-label="Permalink to &quot;3. The analysis itself is inspectable&quot;">​</a></h3><p>Run details retain stages, timelines, tool results, warnings, and model usage. Durable run state supports recovery after interruption, and closing the browser does not cancel the background job.</p><h3 id="_4-team-access-and-agent-access-are-managed-separately" tabindex="-1">4. Team access and agent access are managed separately <a class="header-anchor" href="#_4-team-access-and-agent-access-are-managed-separately" aria-label="Permalink to &quot;4. Team access and agent access are managed separately&quot;">​</a></h3><p>The web app uses users, project membership, and additional grants. An MCP key belongs to a user, can be limited to one or more projects, and may have an expiration time. It never expands the project access of the person who created it.</p><h3 id="_5-models-are-not-hard-coded-in-deployment-files" tabindex="-1">5. Models are not hard-coded in deployment files <a class="header-anchor" href="#_5-models-are-not-hard-coded-in-deployment-files" aria-label="Permalink to &quot;5. Models are not hard-coded in deployment files&quot;">​</a></h3><p>Administrators configure language-model, embedding, and reranker channels in the web app. Provider types include OpenAI, OpenAI-compatible services, DeepSeek, and Anthropic. Whether code reaches an external service depends on the channels the team enables.</p><h2 id="when-it-may-not-be-worth-deploying-yet" tabindex="-1">When it may not be worth deploying yet <a class="header-anchor" href="#when-it-may-not-be-worth-deploying-yet" aria-label="Permalink to &quot;When it may not be worth deploying yet&quot;">​</a></h2><ul><li>The project is one small repository with clear boundaries and a team that already knows it well.</li><li>The team only needs one-time local search and has no reason to share the result.</li><li>The environment cannot provide PostgreSQL, Milvus, a Worker, and model channels.</li><li>The expected outcome is proof of every runtime behavior or a replacement for testing and review.</li><li>Nobody is prepared to define model, network, credential, and repository-path trust boundaries for private code.</li></ul><p>If the earlier scenarios match your team, run the <a href="/en/guide/quick-start">one-machine deployment</a> on a non-critical project and test it with a real cross-repository question.</p>',38)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
